// ==========================================================================
// COMPONENT PAGE GENERATOR
// ==========================================================================
// Automatically generates all files needed for a new component page
// This eliminates the need to manually create repetitive files

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// ==========================================================================
// TEMPLATES
// ==========================================================================

const TEMPLATES = {
  meta: `// ==========================================================================
// {{COMPONENT_NAME_UPPER}} COMPONENT METADATA
// ==========================================================================
// Single source of truth for {{ComponentName}} component documentation
// This replaces hardcoded entries in DocNavItems.jsx

export default {
  // Navigation metadata
  category: '{{CATEGORY}}',
  subCategory: '{{SUBCATEGORY}}',
  menuItem: '{{ComponentName}}',
  routeBase: '/{{routeBase}}',
  icon: '{{ICON}}',
  
  // Page metadata
  header: '{{ComponentName}}',
  subHeader: '{{DESCRIPTION}}',
  
  // Tab configuration
  tabs: [
    {
      name: 'Features',
      route: '/features',
      component: () => import('./features')
    }{{ADDITIONAL_TABS}}
  ],
  
  // Import message for the component
  importMsg: "import { {{ComponentName}} } from 'primereact/{{primereactName}}'",
  
  // Accessibility information
  accessibility: {
    description: "{{ComponentName}} component description for accessibility.",
    example: "<{{ComponentName}} {{EXAMPLE_PROPS}} />"
  }
};`,

  index: `import React from 'react';
import DocPageWrapper from '../../../../Components/Common/DocMain/DocPageWrapper';

export default function {{ComponentName}}Page() {
  return <DocPageWrapper componentName="{{componentName}}" />;
}`,

  features: `import React from 'react';
import DocPanel from '../../../../Components/Common/DocMain/DocPanel';
import CodePreview from '../../../../Components/Common/CodePreview';
import RichText from '../../../../Components/Common/RichText';
import { 
    // Demos
    {{DEMO_IMPORTS}}

    // Sources
    ImportSource,
} from './import';

export const {{ComponentName}}FeatureItems = [
    {
        id: "import",
        sectionNav: "Import",
        sectionDesc: <RichText as="span" content="The <code>import</code> property is used to import the <code>{{ComponentName}}</code> component." />,
        demo: (
            <CodePreview source={ImportSource} snippetName="import" language="jsx" />
        ),
    },
    {{ADDITIONAL_FEATURES}}
];

export default function {{ComponentName}}Features() {
    return (
      <DocPanel 
        Header="{{ComponentName}}" 
        SubHeader="{{DESCRIPTION}}" 
        features={{{ComponentName}}FeatureItems}
      />
    );
  }`,

  import: `// ==========================================================================
// {{ComponentName}} Demo Components Barrel Export
// ==========================================================================
// Centralized exports for all {{ComponentName}} demo components and sources
// This reduces import clutter in {{ComponentName}}FeatureItems.jsx

// Basic Demo
{{DEMO_EXPORTS}}

// {{ComponentName}} Demo Sources Barrel Export
// ==========================================================================
// Centralized exports for all {{ComponentName}} demo source files
export { default as ImportSource } from '../../../../Components/Demo/{{ComponentName}}/Import.jsx?raw';
{{ADDITIONAL_SOURCE_EXPORTS}}`,

  demoImport: `import React from 'react';
import { {{ComponentName}} } from 'primereact/{{primereactName}}';

export default function {{ComponentName}}Import() {
    return (
        <div>
            <h3>{{ComponentName}} Import Example</h3>
            <p>This is a basic {{ComponentName}} component example.</p>
            {/* Add your {{ComponentName}} demo here */}
        </div>
    );
}`
};

// ==========================================================================
// GENERATOR FUNCTIONS
// ==========================================================================

/**
 * Replace template variables with actual values
 */
function replaceTemplateVariables(template, variables) {
  let result = template;
  
  Object.entries(variables).forEach(([key, value]) => {
    const regex = new RegExp(`{{${key}}}`, 'g');
    result = result.replace(regex, value);
  });
  
  return result;
}

/**
 * Generate component name variations
 */
function generateComponentVariations(componentName) {
  const pascalCase = componentName.charAt(0).toUpperCase() + componentName.slice(1);
  const camelCase = componentName.charAt(0).toLowerCase() + componentName.slice(1);
  const kebabCase = componentName.toLowerCase().replace(/([A-Z])/g, '-$1').toLowerCase();
  const upperCase = componentName.toUpperCase();
  
  return {
    ComponentName: pascalCase,
    componentName: camelCase,
    'component-name': kebabCase,
    COMPONENT_NAME_UPPER: upperCase,
    routeBase: kebabCase,
    primereactName: kebabCase
  };
}

/**
 * Generate all files for a component page
 */
export function generateComponentPage(config) {
  const {
    componentName,
    category = 'Elements',
    subCategory = 'Form',
    description = `${componentName} is a component for user interaction.`,
    icon = 'pi pi-compass',
    exampleProps = '',
    additionalTabs = [],
    additionalFeatures = [],
    demoFiles = []
  } = config;

  const variations = generateComponentVariations(componentName);
  const pageFolderName = `${variations.ComponentName}Page`;
  
  // Base paths
  const basePath = path.join(__dirname, '../../Pages/Documentation/UiComponents');
  const pagePath = path.join(basePath, pageFolderName);
  const demoPath = path.join(__dirname, '../../Components/Demo', variations.ComponentName);

  // Create directories
  if (!fs.existsSync(pagePath)) {
    fs.mkdirSync(pagePath, { recursive: true });
  }
  
  if (!fs.existsSync(demoPath)) {
    fs.mkdirSync(demoPath, { recursive: true });
  }

  // Template variables
  const templateVars = {
    ...variations,
    CATEGORY: category,
    SUBCATEGORY: subCategory,
    DESCRIPTION: description,
    ICON: icon,
    EXAMPLE_PROPS: exampleProps,
    ADDITIONAL_TABS: additionalTabs.map(tab => `,
    {
      name: '${tab.name}',
      route: '${tab.route}',
      component: () => import('./${tab.component}')
    }`).join(''),
    DEMO_IMPORTS: demoFiles.map(demo => `    ${demo.name}Demo,`).join('\n    '),
    ADDITIONAL_FEATURES: additionalFeatures.map(feature => `,
    {
        id: "${feature.id}",
        sectionNav: "${feature.sectionNav}",
        sectionDesc: <RichText as="span" content="${feature.description}" />,
        demo: (
            <CodePreview source={${feature.source}} snippetName="${feature.snippetName}" language="jsx" />
        ),
    }`).join(''),
    DEMO_EXPORTS: demoFiles.map(demo => `export { default as ${demo.name}Demo } from '../../../../Components/Demo/${variations.ComponentName}/${demo.name}.jsx';`).join('\n'),
    ADDITIONAL_SOURCE_EXPORTS: demoFiles.map(demo => `export { default as ${demo.name}Source } from '../../../../Components/Demo/${variations.ComponentName}/${demo.name}.jsx?raw';`).join('\n')
  };

  // Generate files
  const files = [
    {
      path: path.join(pagePath, 'meta.js'),
      content: replaceTemplateVariables(TEMPLATES.meta, templateVars)
    },
    {
      path: path.join(pagePath, 'index.jsx'),
      content: replaceTemplateVariables(TEMPLATES.index, templateVars)
    },
    {
      path: path.join(pagePath, 'features.jsx'),
      content: replaceTemplateVariables(TEMPLATES.features, templateVars)
    },
    {
      path: path.join(pagePath, 'import.js'),
      content: replaceTemplateVariables(TEMPLATES.import, templateVars)
    },
    {
      path: path.join(demoPath, 'Import.jsx'),
      content: replaceTemplateVariables(TEMPLATES.demoImport, templateVars)
    }
  ];

  // Write files
  files.forEach(file => {
    fs.writeFileSync(file.path, file.content);
    console.log(`✅ Created: ${file.path}`);
  });

  console.log(`\n🎉 Successfully generated ${componentName} component page!`);
  console.log(`📁 Page folder: ${pagePath}`);
  console.log(`📁 Demo folder: ${demoPath}`);
  console.log(`\n📝 Next steps:`);
  console.log(`1. Add your component demos to: ${demoPath}`);
  console.log(`2. Update the features.jsx file with your specific demos`);
  console.log(`3. The component will be automatically discovered by the system!`);

  return {
    pagePath,
    demoPath,
    files: files.map(f => f.path)
  };
}

// ==========================================================================
// CLI INTERFACE
// ==========================================================================

/**
 * Destroy component page and all associated files
 */
export function destroyComponentPage(componentName) {
  const variations = generateComponentVariations(componentName);
  const pageFolderName = `${variations.ComponentName}Page`;
  
  // Base paths
  const basePath = path.join(__dirname, '../../Pages/Documentation/UiComponents');
  const pagePath = path.join(basePath, pageFolderName);
  const demoPath = path.join(__dirname, '../../Components/Demo', variations.ComponentName);

  const filesToDelete = [];
  const foldersToDelete = [];

  // Check if page folder exists
  if (fs.existsSync(pagePath)) {
    // Get all files in the page folder
    const pageFiles = fs.readdirSync(pagePath);
    pageFiles.forEach(file => {
      filesToDelete.push(path.join(pagePath, file));
    });
    foldersToDelete.push(pagePath);
  }

  // Check if demo folder exists
  if (fs.existsSync(demoPath)) {
    // Get all files in the demo folder
    const demoFiles = fs.readdirSync(demoPath);
    demoFiles.forEach(file => {
      filesToDelete.push(path.join(demoPath, file));
    });
    foldersToDelete.push(demoPath);
  }

  if (filesToDelete.length === 0) {
    console.log(`❌ No files found for component: ${componentName}`);
    return;
  }

  // Delete files
  filesToDelete.forEach(filePath => {
    try {
      fs.unlinkSync(filePath);
      console.log(`🗑️  Deleted: ${filePath}`);
    } catch (error) {
      console.error(`❌ Error deleting file ${filePath}:`, error.message);
    }
  });

  // Delete folders (in reverse order to handle nested folders)
  foldersToDelete.reverse().forEach(folderPath => {
    try {
      fs.rmdirSync(folderPath);
      console.log(`🗑️  Deleted folder: ${folderPath}`);
    } catch (error) {
      console.error(`❌ Error deleting folder ${folderPath}:`, error.message);
    }
  });

  console.log(`\n🎉 Successfully destroyed ${componentName} component page!`);
  console.log(`📁 Deleted page folder: ${pagePath}`);
  console.log(`📁 Deleted demo folder: ${demoPath}`);
  console.log(`\n📝 Note: You may need to restart your development server to see the changes.`);
}

/**
 * CLI function for easy component creation and destruction
 */
export function createComponentCLI() {
  const args = process.argv.slice(2);
  
  if (args.length === 0) {
    console.log(`
🚀 Component Page Generator

Usage: node component-generator.js <command> <componentName> [options]

Commands:
  create <componentName>     Create a new component page
  destroy <componentName>    Destroy an existing component page

Examples:
  node component-generator.js create MyComponent
  node component-generator.js create Password --category=Elements --subCategory=Form
  node component-generator.js create DatePicker --description="Date picker component" --icon="pi pi-calendar"
  node component-generator.js destroy MyComponent
  node component-generator.js destroy Password

Create Options:
  --category=<category>        Component category (default: Elements)
  --subCategory=<subCategory>  Component subcategory (default: Form)
  --description=<description>  Component description
  --icon=<icon>               Icon class (default: pi pi-compass)
  --exampleProps=<props>      Example props for accessibility
    `);
    return;
  }

  const command = args[0];
  const componentName = args[1];

  if (!componentName) {
    console.error('❌ Error: Component name is required');
    console.log('Usage: node component-generator.js <command> <componentName>');
    process.exit(1);
  }

  if (command === 'destroy') {
    try {
      destroyComponentPage(componentName);
    } catch (error) {
      console.error('❌ Error destroying component:', error.message);
      process.exit(1);
    }
    return;
  }

  if (command === 'create') {
    const options = {};

    // Parse options
    args.slice(2).forEach(arg => {
      if (arg.startsWith('--')) {
        const [key, value] = arg.substring(2).split('=');
        options[key] = value;
      }
    });

    try {
      generateComponentPage({
        componentName,
        ...options
      });
    } catch (error) {
      console.error('❌ Error generating component:', error.message);
      process.exit(1);
    }
    return;
  }

  console.error(`❌ Error: Unknown command "${command}"`);
  console.log('Available commands: create, destroy');
  process.exit(1);
}

// Run CLI if called directly
if (import.meta.url === `file://${process.argv[1]}`) {
  createComponentCLI();
}
